<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Peminjaman Kendaraan</title><style>body{font-family:Arial;background:#eaf6ff}.box{max-width:650px;margin:35px auto;background:#fff;padding:30px;border-radius:18px}label{display:block;font-weight:bold;margin:12px 0 6px}input,select,textarea{width:100%;box-sizing:border-box;padding:12px;border:1px solid #ccc;border-radius:9px}button{width:100%;padding:13px;background:#075985;color:#fff;border:0;border-radius:9px;margin-top:15px}</style></head><body><div class="box"><h1>Peminjaman Kendaraan</h1><a href="<?=site_url('dashboard')?>">← Dashboard</a><form method="post" action="<?=site_url('booking/save')?>"><input type="hidden" name="type" value="Kendaraan"><label>Kendaraan</label><select name="item" required><option value="">-- Pilih --</option><?php foreach($vehicles as $v):?><option><?=esc($v)?></option><?php endforeach;?></select><label>Tanggal</label><input type="date" name="date" required><label>Mulai</label><input type="time" name="start" required><label>Selesai</label><input type="time" name="end" required><label>Keperluan</label><textarea name="purpose" required></textarea><button>Ajukan</button></form></div></body></html>
